
<template>

<div class="container"> <div class="card"> <h2>全部活动</h2> <div v-for="act in activities" :key="act.id" class="activity"> <div> <strong>{{ act.title }}</strong> <p class="tip">{{ act.description }}</p> <p class="tip">奖励：{{ act.reward }}</p> <p class="tip"> 时间：{{ format(act.start_at) }} ~ {{ format(act.end_at) }} </p> </div> <button @click="claim(act.id)">领取</button> </div> <p v-if="!activities.length" class="tip">暂无活动</p> </div> </div> </template><script setup> import { ref, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { contentApi } from '../api'; import { useUserStore } from '../stores/user'; const activities = ref([]); const store = useUserStore(); const router = useRouter(); function format(ts) { return new Date(ts).toLocaleDateString(); } async function load() { const res = await contentApi.activities(); activities.value = res.data; } async function claim(id) { if (!store.isLoggedIn) { router.push({ path: '/login', query: { redirect: '/activities' } }); return; } try { const res = await contentApi.claim(id); alert(`领取成功：${res.data.reward}`); } catch (e) { alert(e.message || '领取失败'); } } onMounted(load); </script><style scoped> .activity { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-bottom: 1px solid #f0f0f0; } .activity:last-child { border-bottom: none; } </style>
